SP="$SP" node "$SP/st.mjs" "$SP/p10.mjs"

SP="C:<CLIENT_HOME>/AppData/Local/Temp/claude/C--Workspaces-site-03-app/<NATIVE_ID_0991>/scratchpad"; . "$SP/ev.sh"
sleep 1; T=$(date -u +%FT%T.%3NZ); echo $T
for k in external.data_survives_restart health.caddy health.taiga-back health.postgres external.signup_login_chain; do ev '{"at":"'$T'","type":"fact_verified","summary":"Verified '$k' after VM stop/start","fact":{"key":"'$k'","status":"VERIFIED_REMOTE"},"evidence":["evidence/0038-e2e-after-restart.txt"]}' | grep exit; done
