  const ev=['evidence/0038-e2e-after-restart.txt'];
  fact('external.data_survives_restart',{label:'Data survives a server restart',value:'After gcloud stop/start of <RUN_VM_OR_BOOT_DISK>: login 200, project 1 and user story 1 returned via the public URL; containers auto-restarted; /srv/taiga remounted by UUID',status:'VERIFIED_REMOTE',source:'remote_observation',class:'health',scope:'<PRIVATE_URL_0249> and <RUN_VM_OR_BOOT_DISK> after power cycle at 14:21Z',checked_at:T,fresh_for_minutes:60,evidence:ev,problem:false});
