  fact('external.signup_login_chain',{checked_at:T,evidence:ev,value:'register 201 and login 200 (0034); login 200 and data reads 200 after restart (0038)'});
  fact('gcp.vm',{status:'STALE'}); fact('gcp.taiga_ip',{status:'STALE'}); fact('gcp.firewall_web',{status:'STALE'}); fact('gcp.snapshot_schedule',{status:'STALE'});
