  s.activity={summary:'Deployed and verified; running in Sydney on <RUN_VM_OR_BOOT_DISK>',started_at:T,expected_duration:null,slow_reason:null,waiting_on:'human',last_progress:{at:T,summary:'Data verified to survive a VM stop/start'}};
