  s.handoff.fragile=['Always create source tarballs with git -c core.autocrlf=false archive on this Windows machine (CRLF broke the backend once)','e2-small has 2 GiB RAM + 2 GiB swap: frontend rebuilds take ~14 min; heavy use may need e2-medium','This PC\'s MSYS2 Python CA bundle rejects the LE chain; use SSL_CERT_FILE=Git ca-bundle for scripted checks','Data disk device name can change between boots (sdb->sda); fstab uses UUID and docker waits for /srv/taiga'];
  s.open_items.push({text:'Test account <DEPLOYER_TEST_ACCOUNT> (with project "Persistence check <DEPLOYER_TEST_TOKEN>") remains on the site; deleting it needs the operator\'s approval.',owner:'human',blocking:false});
  s.open_items.push({text:'Operator machine SSH key (user <ACCOUNT>) is in <RUN_VM_OR_BOOT_DISK> instance metadata for administration; project metadata unchanged.',owner:'human',blocking:false});
  s.next={action:'Kept running. Operator to try the site; optionally approve deleting the test account; provide SMTP if password-reset emails are wanted.',decision_owner:'human'};
};
EOF
SP="$SP" node "$SP/st.mjs" "$SP/p11.mjs" || true

SP="C:<CLIENT_HOME>/AppData/Local/Temp/claude/C--Workspaces-site-03-app/<NATIVE_ID_0991>/scratchpad"; . "$SP/ev.sh"
ev '{"type":"stage_change","summary":"Operator asked to tear everything down; preparing the teardown inventory and approval request","stage":{"from":"handoff","to":"teardown"}}' | grep exit
sleep 1; T=$(date -u +%FT%T.%3NZ)
ev '{"at":"'$T'","type":"decision_request","summary":"Asked approval to permanently delete <RUN_VM_OR_BOOT_DISK> (with its boot disk), <RUN_DATA_DISK> (all app data), snapshot schedule <RUN_SNAPSHOT_POLICY>, firewall rule <RUN_FIREWALL> and static IP <RUN_STATIC_IP>; and asked the operator to delete the Cloudflare A record <W3_RUN_HOST_LABEL>","request":{"id":"dec-03","categories":["delete","destructive"]}}' | grep exit
cat > "$SP/p12.mjs" <<EOF
const T='$T';
export default (s, now) => {
  s.stage='teardown';
  s.pending_decision={id:'dec-03',categories:['delete','destructive'],requested_at:T,
