    reversibility:'Irreversible for data. Infrastructure could be recreated from the pinned commits and deploy/ files, but <IP_ADDRESS_115> would not come back.',
    rollback:'None for data. To redeploy, re-run the plan from deploy/ (new IP, new DNS record).',
    success_check:'Same inventory as evidence/0039 shows none of the six resources and no taiga snapshots; <W3_RUN_HOST_LABEL>.<EXPERIMENT_DOMAIN> no longer resolves.',
    reply_options:[{reply:'approve teardown',meaning:'Delete all six listed GCP resources now'},{reply:'keep data disk',meaning:'Delete everything except <RUN_DATA_DISK> (it keeps costing ~USD 1.5/month)'},{reply:'cancel',meaning:'Delete nothing'}]};
