SP="C:<CLIENT_HOME>/AppData/Local/Temp/claude/C--Workspaces-site-03-app/<NATIVE_ID_0991>/scratchpad"; . "$SP/ev.sh"
cat > "$SP/p13.mjs" <<'EOF'
export default (s, now) => {
  s.pending_decision=null;
  s.activity={summary:'Deleting deployment resources (approved dec-03)',started_at:now,expected_duration:{min_minutes:3,max_minutes:10},slow_reason:null,waiting_on:'ai',last_progress:{at:now,summary:'Teardown approved; DNS removal propagating (8.8.8.8 NXDOMAIN, Cloudflare NS still answering)'}};
