ev '{"type":"result","summary":"Static IP <RUN_STATIC_IP> released","outcome":"succeeded","state_change":"<RUN_STATIC_IP> removed","evidence":["evidence/0046-delete-ip.txt"],"related":["evt-0108"]}' | grep exit
sleep 1; T=$(date -u +%FT%T.%3NZ); TD=$(cat "$SP/tdns")
ev '{"at":"'$T'","type":"fact_verified","summary":"Post-teardown inventory: none of the six deployment resources remain; no snapshots or custom images; project metadata fingerprint unchanged","fact":{"key":"teardown.none_left","status":"VERIFIED_REMOTE"},"evidence":["evidence/0047-teardown-inventory-after.txt","evidence/0039-teardown-inventory-before.txt"]}' | grep exit
cat > "$SP/p14.mjs" <<EOF
