export default (s, now, {fact,res}) => {
  s.stage='closed';
  s.pending_decision=null;
  fact('teardown.none_left',{label:'No deployment resources left',value:'0 instances, 0 disks, 0 snapshots, 0 resource policies, 0 addresses, 0 custom images; only the 4 default firewall rules remain; project metadata fingerprint Q6_OW8P-QA8= unchanged',status:'VERIFIED_REMOTE',source:'remote_observation',class:'resource',scope:'compute resources in <CLOUD_PROJECT> (all regions)',checked_at:T,fresh_for_minutes:240,evidence:['evidence/0047-teardown-inventory-after.txt','evidence/0039-teardown-inventory-before.txt'],negative_result:true,control:'The same inventory at 14:45Z (evidence/0039) listed <RUN_VM_OR_BOOT_DISK>, both disks, <RUN_SNAPSHOT_POLICY>, <RUN_STATIC_IP> and <RUN_FIREWALL>'});
  fact('dns.<W3_RUN_HOST_LABEL>_a_record',{label:'DNS A record <W3_RUN_HOST_LABEL>.<EXPERIMENT_DOMAIN>',value:'removed: NXDOMAIN at both Cloudflare authoritative NS, 8.8.8.8 and 1.1.1.1',status:'VERIFIED_REMOTE',source:'remote_observation',class:'network',scope:'<W3_RUN_HOST_LABEL>.<EXPERIMENT_DOMAIN> at denver/<DNS_RESOLVER_B>, dns.google and 1.1.1.1',checked_at:TD,fresh_for_minutes:240,evidence:['evidence/0045-dns-removed-check2.txt'],negative_result:true,control:'Same queries returned the <EXPERIMENT_DOMAIN> apex A records'});
  for (const id of ['<RUN_VM_OR_BOOT_DISK>','<RUN_VM_OR_BOOT_DISK>-boot','<RUN_VM_OR_BOOT_DISK>-ephemeral-none','<RUN_DATA_DISK>','<RUN_SNAPSHOT_POLICY>','<RUN_FIREWALL>','<RUN_STATIC_IP>']) res(id,{lifecycle:'deleted',evidence_fact:'teardown.none_left'});
  res('cf-<W3_RUN_HOST_LABEL>-a',{lifecycle:'deleted',evidence_fact:'dns.<W3_RUN_HOST_LABEL>_a_record'});
  const stale=['health.caddy','health.taiga-back','health.postgres','external.https_tls','external.signup_login_chain','external.data_survives_restart','gcp.vm','gcp.data_disk','gcp.snapshot_schedule','gcp.firewall_web','gcp.taiga_ip','source.taiga-back.deployed_ref','source.taiga-front.deployed_ref'];
  for (const f of s.facts) if (stale.includes(f.key) && f.checked_at) f.status='STALE';
  s.secrets=s.secrets.map(x=>x.name==='EMAIL_HOST_PASSWORD'?x:{...x,location:'destroyed with <RUN_DATA_DISK> (/srv/taiga/app/secrets.env); never stored elsewhere',availability:'missing'});
