  s.handoff.last_safe_state=T.slice(0,19)+'Z: all deployment resources deleted and verified; DNS record removed.';
  s.handoff.rollback_anchor=null;
  s.handoff.known_unverified=['Billing: final partial-day charges will still appear on the invoice; not checked'];
  s.handoff.fragile=[];
  s.next={action:'Nothing more to do',decision_owner:'none'};
};
